using ACWA.Services.Interfaces;
using ACWA.Services.TransportModels.User.Request;
using ACWA.Services.TransportModels.User.Response;
using ACWA.Web.Extensions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Threading.Tasks;

namespace ACWA.Web.Controllers
{
    [Authorize(Policy = "ApiUser")]
    [Route("api/[controller]")]
    [ApiController]
    public class UsersController : ControllerBase
    {
        private readonly IUserService _userService;

        public UsersController(IUserService userService)
        {
            _userService = userService;
        }

        // GET: api/users
        [HttpGet]
        public async Task<PaginationHelper<UserResponse>> GetUsers([FromQuery] int page = 1, [FromQuery] int pageSize = 10)
        {
            // For generate new users
            //var genUsers = new Generate().GetUsers(50);
            //foreach (var user in genUsers)
            //{
            //    await _userService.AddUserAsync(user);
            //}

            int totalCount = await _userService.GetUsersCountAsync();
            var users = await _userService.GetAllUsersAsync(pageSize * (page - 1), pageSize);

            return new PaginationHelper<UserResponse>
            {
                Entities = users,
                PageNumber = page,
                PageSize = pageSize,
                TotalPages = (totalCount / pageSize) + (totalCount % pageSize == 0 ? 0 : 1)
            };
        }

        // GET: api/users/id
        [HttpGet("{id}")]
        public async Task<IActionResult> GetUser([FromRoute] Guid id)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            var user = await _userService.GetUserByIdAsync(id);

            if (user == null)
            {
                return NotFound();
            }

            return Ok(user);
        }

        // GET: api/users/full/id
        [HttpGet("full/{id}")]
        public async Task<IActionResult> GetUserForEdit([FromRoute] Guid id)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            var user = await _userService.GetUserForEditByIdAsync(id);

            if (user == null)
            {
                return NotFound();
            }

            return Ok(user);
        }

        // PUT: api/users/update
        [HttpPut("{update}")]
        public async Task<IActionResult> UpdateUser([FromBody] UpdateUserRequest model)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            try
            {
                await _userService.UpdateUserAsync(model);
            }
            catch (Exception exp)
            {
                return BadRequest(exp);
            }

            return NoContent();
        }

        // POST: api/users/add
        [HttpPost("{add}")]
        public async Task<IActionResult> AddUser([FromBody] AddUserRequest model)
        {
            if (!ModelState.IsValid)
            {
                return BadRequest(ModelState);
            }

            try
            {
                await _userService.AddUserAsync(model);
            }
            catch (Exception exp)
            {
                return BadRequest(exp);
            }

            return NoContent();
        }

        // DELETE: api/users/id
        [HttpDelete("{id}")]
        public async Task<IActionResult> DeleteUser([FromRoute] Guid id)
        {
            try
            {
                await _userService.DeleteUserAsync(id);
            }
            catch (Exception exp)
            {
                return BadRequest(exp);
            }

            return NoContent();
        }
    }
}
